// Build simplified HTML for Android TV / Kiosk display
// Color-coded status, dark theme, auto-refresh, read-only
// NO raw logs, NO file paths, NO interactive controls

const fileData = $input.first().json.data;
let statusData;
try {
  statusData = JSON.parse(fileData);
} catch (e) {
  const errorHtml = `<!DOCTYPE html><html><head><meta charset="UTF-8"><title>Agent Loop ??? Error</title><style>body{background:#1a1a2e;color:#e74c3c;font:28px monospace;padding:60px;text-align:center}h1{margin-bottom:40px}</style></head><body><h1>ERROR</h1><p>Cannot read status data</p></body></html>`;
  return [{ json: { html: errorHtml } }];
}

const status = String(statusData.overall_status || 'UNKNOWN').toUpperCase();
const runsFound = Number(statusData.runs_found) || 0;
const withDecision = Number(statusData.runs_with_controller_decision) || 0;
const withAgent = Number(statusData.runs_with_agent_launched) || 0;
const latestRunId = String(statusData.latest_run_id || 'N/A');
const generatedAt = statusData.generated_at || 'Unknown';

// Map status to CSS class and icon
let statusClass = 'unknown';
let statusIcon = '???';
let statusLabel = 'UNKNOWN';

if (status === 'RED_BLOCK') { statusClass = 'red'; statusIcon = '????'; statusLabel = 'RED BLOCK'; }
else if (status === 'YELLOW_REVIEW') { statusClass = 'yellow'; statusIcon = '??????'; statusLabel = 'YELLOW REVIEW'; }
else if (status === 'NEEDS_VALIDATION') { statusClass = 'yellow'; statusIcon = '????'; statusLabel = 'NEEDS VALIDATION'; }
else if (status === 'TOOL_GAP') { statusClass = 'yellow'; statusIcon = '????'; statusLabel = 'TOOL GAP'; }
else if (status === 'GREEN_SAFE') { statusClass = 'green'; statusIcon = '???'; statusLabel = 'GREEN SAFE'; }
else if (status === 'STALE') { statusClass = 'grey'; statusIcon = '???'; statusLabel = 'STALE'; }

const html = `<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <meta http-equiv="refresh" content="30">
  <title>Agent Loop ??? TV Status</title>
  <style>
    * { margin: 0; padding: 0; box-sizing: border-box; }
    body {
      background: #1a1a2e;
      color: #e0e0e0;
      font-family: 'Courier New', monospace;
      padding: 40px 60px;
      min-height: 100vh;
    }
    h1 {
      font-size: 36px;
      margin-bottom: 10px;
      color: #a0a0b0;
      letter-spacing: 2px;
      text-transform: uppercase;
    }
    .subtitle {
      font-size: 18px;
      color: #666;
      margin-bottom: 40px;
    }
    .status-box {
      padding: 40px;
      border-radius: 16px;
      margin-bottom: 30px;
      text-align: center;
      border: 3px solid transparent;
    }
    .status-box.red {
      background: rgba(231, 76, 60, 0.2);
      border-color: #e74c3c;
      box-shadow: 0 0 60px rgba(231, 76, 60, 0.15);
    }
    .status-box.yellow {
      background: rgba(243, 156, 18, 0.2);
      border-color: #f39c12;
      box-shadow: 0 0 60px rgba(243, 156, 18, 0.15);
    }
    .status-box.green {
      background: rgba(39, 174, 96, 0.2);
      border-color: #27ae60;
      box-shadow: 0 0 60px rgba(39, 174, 96, 0.15);
    }
    .status-box.grey {
      background: rgba(127, 140, 141, 0.2);
      border-color: #7f8c8d;
    }
    .status-box.unknown {
      background: rgba(149, 165, 166, 0.15);
      border-color: #95a5a6;
    }
    .status-icon {
      font-size: 72px;
      margin-bottom: 20px;
    }
    .status-label {
      font-size: 48px;
      font-weight: bold;
      letter-spacing: 4px;
      margin-bottom: 20px;
    }
    .red .status-label { color: #e74c3c; }
    .yellow .status-label { color: #f39c12; }
    .green .status-label { color: #27ae60; }
    .grey .status-label { color: #7f8c8d; }
    .stats-grid {
      display: grid;
      grid-template-columns: repeat(3, 1fr);
      gap: 20px;
      margin-bottom: 30px;
    }
    .stat-card {
      background: rgba(255, 255, 255, 0.05);
      border-radius: 12px;
      padding: 25px;
      text-align: center;
    }
    .stat-value {
      font-size: 48px;
      font-weight: bold;
      color: #fff;
    }
    .stat-label {
      font-size: 16px;
      color: #888;
      margin-top: 8px;
      text-transform: uppercase;
      letter-spacing: 1px;
    }
    .footer {
      position: fixed;
      bottom: 20px;
      left: 0;
      right: 0;
      text-align: center;
      color: #444;
      font-size: 14px;
    }
    .disclaimer {
      color: #555;
      font-size: 14px;
      margin-top: 10px;
    }
  </style>
</head>
<body>
  <h1>???? Agent Loop Status</h1>
  <p class="subtitle">mission-driven-agent-loop ??? Phase 3B</p>

  <div class="status-box ${statusClass}">
    <div class="status-icon">${statusIcon}</div>
    <div class="status-label">${statusLabel}</div>
  </div>

  <div class="stats-grid">
    <div class="stat-card">
      <div class="stat-value">${runsFound}</div>
      <div class="stat-label">Total Runs</div>
    </div>
    <div class="stat-card">
      <div class="stat-value">${withDecision}</div>
      <div class="stat-label">With Decision</div>
    </div>
    <div class="stat-card">
      <div class="stat-value">${withAgent}</div>
      <div class="stat-label">Agent Launched</div>
    </div>
  </div>

  <p class="disclaimer">???? READ-ONLY ??? No agents running ??? Auto-refresh: 30s</p>
  <p class="disclaimer">Latest: ${latestRunId} @ ${generatedAt}</p>

  <div class="footer">Phase 3B ??? n8n Integration Blueprint</div>
</body>
</html>`;

return [{ json: { html: html } }];
